render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#sims-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const baseColor = params.plumbob_color || '#22EE33';
const spinSpeed = params.spin_speed !== undefined ? params.spin_speed : 1.2;
const textContent = params.text_content !== undefined ? params.text_content : 'SUL SUL!';
const textColor = params.text_color || '#FFFFFF';
const textSize = params.text_size || 48;
const revealSpeed = params.reveal_speed || 1.0;
const floatSpeed = params.float_speed !== undefined ? params.float_speed : 1.5;
const size = params.plumbob_size || 110;
const glowIntensity = params.glow_intensity !== undefined ? params.glow_intensity : 0.7;
const sparkles = params.sparkle_effects !== false;
const showShadow = params.show_shadow !== false;
const bgColor = params.bg_color || '#121824';

// Fondo
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

const cx = width / 2;
const cy = height / 2;
const floatOffset = Math.sin(time * floatSpeed * 2) * 16;

// Cálculo del ciclo de desplazamiento (Transición suave 0 -> 1 -> 0)
const rawCycle = (Math.sin(time * revealSpeed - Math.PI / 2) + 1) / 2;
const animProgress = rawCycle * rawCycle * (3 - 2 * rawCycle); // Smoothstep easing

// Posiciones dinámicas
const shiftDistance = size * 1.2;
const diamondX = cx - (shiftDistance * animProgress);
const diamondY = cy + floatOffset;

const textX = cx - (size * 0.2) + (shiftDistance * 0.8 * animProgress);
const textAlpha = animProgress;
const textScale = 0.6 + 0.4 * animProgress;

function hexToRgb(hex) {
  let result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : { r: 34, g: 238, b: 51 };
}

const rgb = hexToRgb(baseColor);

// 1. SOMBRA EN EL SUELO (Acompaña al diamante)
if (showShadow) {
  c.save();
  const shadowY = cy + size * 1.5;
  const shadowScale = 1 - (floatOffset / 70);
  const shadowGrad = c.createRadialGradient(diamondX, shadowY, 5, diamondX, shadowY, size * 0.8 * shadowScale);
  shadowGrad.addColorStop(0, 'rgba(0, 0, 0, 0.45)');
  shadowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  c.fillStyle = shadowGrad;
  c.beginPath();
  c.ellipse(diamondX, shadowY, size * 0.75 * shadowScale, size * 0.22 * shadowScale, 0, 0, Math.PI * 2);
  c.fill();
  c.restore();
}

// 2. TEXTO APARIECIENDO AL LADO DERECHO
if (textAlpha > 0.01) {
  c.save();
  c.font = 'bold ' + textSize + 'px "Arial Rounded MT Bold", "Comfortaa", "Fredoka", sans-serif';
  c.textAlign = 'left';
  c.textBaseline = 'middle';

  c.translate(textX, cy);
  c.scale(textScale, textScale);

  c.shadowColor = baseColor;
  c.shadowBlur = 20 * glowIntensity;
  c.fillStyle = textColor;
  c.globalAlpha = textAlpha;
  c.fillText(textContent, 0, 0);
  c.restore();
}

// 3. MODELADO Y RENDER 3D DEL DIAMANTE (Octaedro)
const h = size * 1.8;
const r = size * 0.55;
const numSides = 6;
const rotY = time * spinSpeed * 2;
const pitch = 0.18;

const topV = [0, -h / 2, 0];
const botV = [0, h / 2, 0];
const midV = [];

for (let i = 0; i < numSides; i++) {
  const ang = (i / numSides) * Math.PI * 2;
  midV.push([Math.cos(ang) * r, 0, Math.sin(ang) * r]);
}

function project(v) {
  let x = v[0];
  let y = v[1];
  let z = v[2];

  let x1 = x * Math.cos(rotY) + z * Math.sin(rotY);
  let z1 = -x * Math.sin(rotY) + z * Math.cos(rotY);
  let y1 = y;

  let y2 = y1 * Math.cos(pitch) - z1 * Math.sin(pitch);
  let z2 = y1 * Math.sin(pitch) + z1 * Math.cos(pitch);

  return { x: diamondX + x1, y: diamondY + y2, z: z2 };
}

const pTop = project(topV);
const pBot = project(botV);
const pMids = midV.map(v => project(v));

const faces = [];
for (let i = 0; i < numSides; i++) {
  const next = (i + 1) % numSides;
  faces.push({
    pts: [pTop, pMids[i], pMids[next]],
    avgZ: (pTop.z + pMids[i].z + pMids[next].z) / 3,
    isTop: true
  });
  faces.push({
    pts: [pBot, pMids[next], pMids[i]],
    avgZ: (pBot.z + pMids[next].z + pMids[i].z) / 3,
    isTop: false
  });
}

faces.sort((a, b) => a.avgZ - b.avgZ);

const lightDir = [0.4, -0.6, 0.7];

faces.forEach(f => {
  const p0 = f.pts[0];
  const p1 = f.pts[1];
  const p2 = f.pts[2];

  const nx = (p1.y - p0.y) * (p2.z - p0.z) - (p1.z - p0.z) * (p2.y - p0.y);
  const ny = (p1.z - p0.z) * (p2.x - p0.x) - (p1.x - p0.x) * (p2.z - p0.z);
  const nz = (p1.x - p0.x) * (p2.y - p0.y) - (p1.y - p0.y) * (p2.x - p0.x);
  const len = Math.hypot(nx, ny, nz) || 1;

  let dot = Math.abs((nx * lightDir[0] + ny * lightDir[1] + nz * lightDir[2]) / len);
  let brightness = 0.45 + dot * 0.55;
  if (f.isTop) brightness *= 1.15;

  const cr = Math.min(255, Math.floor(rgb.r * brightness));
  const cg = Math.min(255, Math.floor(rgb.g * brightness));
  const cb = Math.min(255, Math.floor(rgb.b * brightness));

  c.save();
  c.beginPath();
  c.moveTo(p0.x, p0.y);
  c.lineTo(p1.x, p1.y);
  c.lineTo(p2.x, p2.y);
  c.closePath();

  c.fillStyle = 'rgb(' + cr + ',' + cg + ',' + cb + ')';
  c.fill();

  c.strokeStyle = 'rgba(255, 255, 255, 0.35)';
  c.lineWidth = 1;
  c.stroke();
  c.restore();
});

// Glow Neón alrededor del Diamante
if (glowIntensity > 0) {
  c.save();
  c.globalCompositeOperation = 'screen';
  const glowGrad = c.createRadialGradient(diamondX, diamondY, size * 0.2, diamondX, diamondY, size * 1.2);
  glowGrad.addColorStop(0, 'rgba(' + rgb.r + ',' + rgb.g + ',' + rgb.b + ',' + (0.35 * glowIntensity) + ')');
  glowGrad.addColorStop(1, 'rgba(0,0,0,0)');
  c.fillStyle = glowGrad;
  c.fillRect(diamondX - size * 1.5, diamondY - size * 1.5, size * 3, size * 3);
  c.restore();
}

// 4. DESTELLOS Y CHISPAS
if (sparkles) {
  c.save();
  c.fillStyle = '#FFFFFF';
  for (let s = 0; s < 4; s++) {
    const sparkAngle = time * 2 + s * 1.57;
    const sparkDist = size * (0.4 + Math.sin(time * 3 + s) * 0.2);
    const sx = diamondX + Math.cos(sparkAngle) * sparkDist;
    const sy = diamondY + Math.sin(sparkAngle * 1.3) * (sparkDist * 0.7);
    const sparkSize = 2 + Math.sin(time * 5 + s) * 2;

    if (sparkSize > 0.5) {
      c.shadowColor = '#FFFFFF';
      c.shadowBlur = 8;
      c.beginPath();
      c.arc(sx, sy, sparkSize, 0, Math.PI * 2);
      c.fill();
    }
  }
  c.restore();
}
